        self.path = path
    def showPage(self):
        pass
    def drawString(self, x, y, text):
        pass
    def save(self):
        with open(self.path, "wb") as f:
            f.write(b"%PDF-1.4\n%%EOF\n")

pdfgen.Canvas = CanvasMock

sys.modules["reportlab"] = reportlab
